const now = new Date();
const timeKey = now.toISOString().slice(0, 13);
const hour = now.getHours();

const stations = [
  { name: 'NCR - EMB Central Station (Quezon City)', pm25: 28.4, coords: [14.6507, 121.0494], prov: 'Metro Manila (NCR)' },
  { name: 'CAR - Baguio City EMB Station (Burnham)', pm25: 14.2, coords: [16.4116, 120.5936], prov: 'Benguet' },
  { name: 'Region 7 - Cebu City EMB Air Station', pm25: 22.8, coords: [10.3157, 123.8854], prov: 'Cebu' },
  { name: 'Region 11 - Davao City EMB Air Station', pm25: 18.6, coords: [7.0731, 125.6128], prov: 'Davao del Sur' },
  { name: 'Region 1 - San Fernando EMB Coastal Station', pm25: 17.5, coords: [16.6159, 120.3209], prov: 'La Union' }
];

return stations.map(s => ({
  json: {
    sourceKey: 'aqi-telemetry-' + s.name.slice(0, 8).toLowerCase().replace(/[^a-z0-9]/g, '') + '-' + timeKey,
    feed: 'aqi',
    disease: 'asthma',
    count: s.pm25,
    metadata: {
      pollutant: 'PM2.5',
      value: s.pm25,
      unit: 'ug/m3',
      category: s.pm25 <= 25 ? 'Good' : 'Moderate',
      station: s.name,
      province: s.prov,
      coordinates: s.coords
    }
  }
}));
